from solution import pairs_sum_to_zero
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def reference(l):
    n = len(l)
    for i in range(n):
        for j in range(i + 1, n):
            if l[i] + l[j] == 0:
                return True
    return False


# --- explicit spec examples ---
def test_spec_example_1():
    assert pairs_sum_to_zero([1, 3, 5, 0]) is False


def test_spec_example_2():
    assert pairs_sum_to_zero([1, 3, -2, 1]) is False


def test_spec_example_3():
    assert pairs_sum_to_zero([1, 2, 3, 7]) is False


def test_spec_example_4():
    assert pairs_sum_to_zero([2, 4, -5, 3, 5, 7]) is True


def test_spec_example_singleton():
    assert pairs_sum_to_zero([1]) is False


# --- boundary / defect-focused examples ---
def test_empty_list_is_false():
    assert pairs_sum_to_zero([]) is False


def test_single_zero_is_false():
    assert pairs_sum_to_zero([0]) is False


def test_two_zeros_is_true():
    assert pairs_sum_to_zero([0, 0]) is True


def test_three_zeros_is_true():
    assert pairs_sum_to_zero([0, 0, 0]) is True


def test_zero_pair_among_others_is_true():
    assert pairs_sum_to_zero([1, 2, 0, 3, 0]) is True


def test_single_zero_with_non_complementary_is_false():
    assert pairs_sum_to_zero([1, 3, 5, 0]) is False


def test_opposite_pair_is_true():
    assert pairs_sum_to_zero([5, -5]) is True


def test_same_nonzero_twice_is_false():
    assert pairs_sum_to_zero([5, 5]) is False
    assert pairs_sum_to_zero([-3, -3]) is False


def test_returns_bool_type():
    assert pairs_sum_to_zero([2, 4, -5, 3, 5, 7]) is True
    assert pairs_sum_to_zero([1, 2, 3]) is False
    assert isinstance(pairs_sum_to_zero([0, 0]), bool)
    assert isinstance(pairs_sum_to_zero([1]), bool)


# --- property tests ---
@given(st.lists(st.integers(min_value=-10, max_value=10), min_size=0, max_size=8))
def test_equivalence_to_brute_force_reference(l):
    assert pairs_sum_to_zero(list(l)) is reference(list(l))


@given(st.lists(st.integers(min_value=-5, max_value=5), min_size=0, max_size=6))
def test_zero_count_determines_zero_only_lists(l):
    zeros = [0] * len(l)
    # list of all zeros: True iff length >= 2
    n = len(l)
    expected = n >= 2
    assert pairs_sum_to_zero(zeros) is expected


@given(st.integers(min_value=-100, max_value=100))
def test_singleton_always_false(x):
    assert pairs_sum_to_zero([x]) is False


def test_empty_always_false_property():
    assert pairs_sum_to_zero([]) is False


@given(st.lists(st.integers(min_value=-20, max_value=20), min_size=0, max_size=10))
def test_permutation_invariance(l):
    import random
    # deterministic permutation: reverse and rotate
    rev = list(reversed(l))
    assert pairs_sum_to_zero(l) is pairs_sum_to_zero(rev)
    if len(l) > 1:
        rotated = l[1:] + l[:1]
        assert pairs_sum_to_zero(l) is pairs_sum_to_zero(rotated)


@given(st.lists(st.integers(min_value=-20, max_value=20), min_size=0, max_size=10))
def test_negation_symmetry(l):
    neg = [-x for x in l]
    assert pairs_sum_to_zero(l) is pairs_sum_to_zero(neg)


@given(st.lists(st.integers(min_value=1, max_value=100), min_size=0, max_size=10))
def test_all_strictly_positive_is_false(l):
    assume(all(x != 0 for x in l))
    assert pairs_sum_to_zero(l) is False


@given(st.lists(st.integers(min_value=-100, max_value=-1), min_size=0, max_size=10))
def test_all_strictly_negative_is_false(l):
    assert pairs_sum_to_zero(l) is False


@given(
    st.lists(st.integers(min_value=-20, max_value=20), min_size=0, max_size=8),
    st.integers(min_value=-20, max_value=20),
)
def test_adding_complementary_pair_forces_true(l, k):
    # adding both k and -k (as two new distinct positions) must yield True,
    # except the k==0 case still needs two zeros which we do add.
    extended = list(l) + [k, -k]
    assert pairs_sum_to_zero(extended) is True


@given(st.lists(st.integers(min_value=-10, max_value=10), min_size=0, max_size=8))
def test_duplicating_list_preserves_result(l):
    # idempotence-ish: l+l has a zero-sum pair iff l does, OR l contains 0
    # (since duplication creates a second copy of 0). Check against reference.
    assert pairs_sum_to_zero(l + l) is reference(l + l)
    if 0 not in l:
        assert pairs_sum_to_zero(l + l) is pairs_sum_to_zero(l)


@given(st.lists(st.integers(min_value=-10, max_value=10), min_size=2, max_size=10))
def test_distinct_indices_not_distinct_values(l):
    # reference explicitly requires i<j; result must match that, catching
    # set-collapsing bugs around [0,0].
    assert pairs_sum_to_zero(l) is reference(l)
